descriptor.templateCss:
.general-card-container {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #64B856;
  padding: 16px 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  overflow: hidden;
}

.general-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 24px;
}

.general-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
  white-space: nowrap;
}

.general-icon {
  font-size: 16px;
}

.general-status-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 2px 10px;
  border-radius: 20px;
  white-space: nowrap;
  transition: all 0.3s ease;
}

.general-status-badge.normal {
  color: #64B856;
  border: 1.5px solid #64B856;
  background: rgba(100, 184, 86, 0.08);
}

.general-status-badge.alert {
  color: #f59e0b;
  border: 1.5px solid #f59e0b;
  background: rgba(245, 158, 11, 0.08);
}

.general-metric-body {
  display: flex;
  align-items: center;
  margin: 6px 0;
  min-height: 40px;
}

.metric-text-value {
  font-size: 28px;
  font-weight: 800;
  color: #818cf8;
  letter-spacing: 0.8px;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.general-divider {
  width: 100%;
  height: 1px;
  background: rgba(148, 163, 184, 0.15);
  margin: 8px 0 10px 0;
}

.general-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  min-height: 38px;
}

.footer-left {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  max-width: 70%;
}

.footer-left .footer-label {
  font-size: 13px;
  font-weight: 500;
  color: #94a3b8;
  white-space: nowrap;
}

.footer-left .footer-subtext {
  font-size: 12px;
  color: #556987;
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.footer-right {
  display: flex;
  align-items: flex-end;
}

.footer-right .footer-value {
  font-size: 14px;
  font-weight: 700;
  color: #64B856;
  white-space: nowrap;
}

descriptor.controllerScript:
self.onInit = function() {
  self.onDataUpdated();
};

self.onDataUpdated = function() {
  var data = self.ctx.data;
  var modoVal = "OFF-GRID";
  var fuenteVal = "Solar + BESS";
  var estadoVal = "ESTABLE";

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var lastVal = String(item.data[item.data.length - 1][1]);
        var keyName = (item.dataKey.label || item.dataKey.name || "").toLowerCase();

        if (keyName.indexOf("modo") !== -1 || i === 0) {
          modoVal = lastVal.toUpperCase();
        } else if (keyName.indexOf("fuente") !== -1 || i === 1) {
          fuenteVal = lastVal;
        } else if (keyName.indexOf("estado") !== -1 || keyName.indexOf("sistema") !== -1 || i === 2) {
          estadoVal = lastVal.toUpperCase();
        }
      }
    }
  }

  var isAlert = estadoVal.indexOf("FALLA") !== -1 || estadoVal.indexOf("ALERTA") !== -1 || estadoVal.indexOf("WARN") !== -1;

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var elModo = container.querySelector('#general-mode-value');
    if (elModo) elModo.textContent = modoVal;

    var elFuente = container.querySelector('#general-source-value');
    if (elFuente) elFuente.textContent = fuenteVal;

    var elEstado = container.querySelector('#general-state-value');
    if (elEstado) {
      elEstado.textContent = estadoVal;
      elEstado.style.color = isAlert ? "#f59e0b" : "#64B856";
    }

    var elBadge = container.querySelector('#general-status-badge');
    if (elBadge) {
      elBadge.textContent = isAlert ? "ALERTA" : "NORMAL";
      elBadge.className = "general-status-badge " + (isAlert ? "alert" : "normal");
    }
  }
};

self.onDestroy = function() {};
